<meta name="component" content="StatesPage">

<!-- Every rhythm component in every fixture state it declares, a captioned
     cell each, in a grid that scrolls (docs/ui.md §6.1). -->
<scroll id="Page">
  <div id="Cells">
    <section class="cell" data-member="song-select"><span class="caption">{$captions.songSelect_default}</span><div class="stage"><RhythmSongSelect title={$songSelect_default.title} selected={$songSelect_default.selected} previewing={$songSelect_default.previewing} status={$songSelect_default.status} songs={$songSelect_default_songs} /></div></section>
    <section class="cell" data-member="song-select"><span class="caption">{$captions.songSelect_selected}</span><div class="stage"><RhythmSongSelect title={$songSelect_selected.title} selected={$songSelect_selected.selected} previewing={$songSelect_selected.previewing} status={$songSelect_selected.status} songs={$songSelect_selected_songs} /></div></section>
    <section class="cell" data-member="song-select"><span class="caption">{$captions.songSelect_disabled}</span><div class="stage"><RhythmSongSelect title={$songSelect_disabled.title} selected={$songSelect_disabled.selected} previewing={$songSelect_disabled.previewing} status={$songSelect_disabled.status} songs={$songSelect_disabled_songs} /></div></section>
    <section class="cell" data-member="song-select"><span class="caption">{$captions.songSelect_empty}</span><div class="stage"><RhythmSongSelect title={$songSelect_empty.title} selected={$songSelect_empty.selected} previewing={$songSelect_empty.previewing} status={$songSelect_empty.status} songs={$songSelect_empty_songs} /></div></section>
    <section class="cell" data-member="song-select"><span class="caption">{$captions.songSelect_loading}</span><div class="stage"><RhythmSongSelect title={$songSelect_loading.title} selected={$songSelect_loading.selected} previewing={$songSelect_loading.previewing} status={$songSelect_loading.status} songs={$songSelect_loading_songs} /></div></section>
    <section class="cell" data-member="song-select"><span class="caption">{$captions.songSelect_error}</span><div class="stage"><RhythmSongSelect title={$songSelect_error.title} selected={$songSelect_error.selected} previewing={$songSelect_error.previewing} status={$songSelect_error.status} songs={$songSelect_error_songs} /></div></section>
    <section class="cell" data-member="song-select"><span class="caption">{$captions.songSelect_overflow}</span><div class="stage"><RhythmSongSelect title={$songSelect_overflow.title} selected={$songSelect_overflow.selected} previewing={$songSelect_overflow.previewing} status={$songSelect_overflow.status} songs={$songSelect_overflow_songs} /></div></section>
    <section class="cell" data-member="difficulty"><span class="caption">{$captions.difficulty_default}</span><div class="stage"><RhythmDifficulty title={$difficulty_default.title} selected={$difficulty_default.selected} levels={$difficulty_default_levels} /></div></section>
    <section class="cell" data-member="difficulty"><span class="caption">{$captions.difficulty_selected}</span><div class="stage"><RhythmDifficulty title={$difficulty_selected.title} selected={$difficulty_selected.selected} levels={$difficulty_selected_levels} /></div></section>
    <section class="cell" data-member="difficulty"><span class="caption">{$captions.difficulty_disabled}</span><div class="stage"><RhythmDifficulty title={$difficulty_disabled.title} selected={$difficulty_disabled.selected} levels={$difficulty_disabled_levels} /></div></section>
    <section class="cell" data-member="difficulty"><span class="caption">{$captions.difficulty_empty}</span><div class="stage"><RhythmDifficulty title={$difficulty_empty.title} selected={$difficulty_empty.selected} levels={$difficulty_empty_levels} /></div></section>
    <section class="cell" data-member="difficulty"><span class="caption">{$captions.difficulty_overflow}</span><div class="stage"><RhythmDifficulty title={$difficulty_overflow.title} selected={$difficulty_overflow.selected} levels={$difficulty_overflow_levels} /></div></section>
    <section class="cell" data-member="judgement"><span class="caption">{$captions.judgement_default}</span><div class="stage"><RhythmJudgement judgement={$judgement_default.judgement} label={$judgement_default.label} timing={$judgement_default.timing} hit={$judgement_default.hit} combo={$judgement_default.combo} broken={$judgement_default.broken} /></div></section>
    <section class="cell" data-member="judgement"><span class="caption">{$captions.judgement_great}</span><div class="stage"><RhythmJudgement judgement={$judgement_great.judgement} label={$judgement_great.label} timing={$judgement_great.timing} hit={$judgement_great.hit} combo={$judgement_great.combo} broken={$judgement_great.broken} /></div></section>
    <section class="cell" data-member="judgement"><span class="caption">{$captions.judgement_good}</span><div class="stage"><RhythmJudgement judgement={$judgement_good.judgement} label={$judgement_good.label} timing={$judgement_good.timing} hit={$judgement_good.hit} combo={$judgement_good.combo} broken={$judgement_good.broken} /></div></section>
    <section class="cell" data-member="judgement"><span class="caption">{$captions.judgement_miss}</span><div class="stage"><RhythmJudgement judgement={$judgement_miss.judgement} label={$judgement_miss.label} timing={$judgement_miss.timing} hit={$judgement_miss.hit} combo={$judgement_miss.combo} broken={$judgement_miss.broken} /></div></section>
    <section class="cell" data-member="judgement"><span class="caption">{$captions.judgement_none}</span><div class="stage"><RhythmJudgement judgement={$judgement_none.judgement} label={$judgement_none.label} timing={$judgement_none.timing} hit={$judgement_none.hit} combo={$judgement_none.combo} broken={$judgement_none.broken} /></div></section>
    <section class="cell" data-member="judgement"><span class="caption">{$captions.judgement_overflow}</span><div class="stage"><RhythmJudgement judgement={$judgement_overflow.judgement} label={$judgement_overflow.label} timing={$judgement_overflow.timing} hit={$judgement_overflow.hit} combo={$judgement_overflow.combo} broken={$judgement_overflow.broken} /></div></section>
    <section class="cell" data-member="score-hud"><span class="caption">{$captions.scoreHud_default}</span><div class="stage"><RhythmScoreHud score={$scoreHud_default.score} accuracy={$scoreHud_default.accuracy} life={$scoreHud_default.life} danger={$scoreHud_default.danger} failed={$scoreHud_default.failed} progress={$scoreHud_default.progress} /></div></section>
    <section class="cell" data-member="score-hud"><span class="caption">{$captions.scoreHud_danger}</span><div class="stage"><RhythmScoreHud score={$scoreHud_danger.score} accuracy={$scoreHud_danger.accuracy} life={$scoreHud_danger.life} danger={$scoreHud_danger.danger} failed={$scoreHud_danger.failed} progress={$scoreHud_danger.progress} /></div></section>
    <section class="cell" data-member="score-hud"><span class="caption">{$captions.scoreHud_failed}</span><div class="stage"><RhythmScoreHud score={$scoreHud_failed.score} accuracy={$scoreHud_failed.accuracy} life={$scoreHud_failed.life} danger={$scoreHud_failed.danger} failed={$scoreHud_failed.failed} progress={$scoreHud_failed.progress} /></div></section>
    <section class="cell" data-member="score-hud"><span class="caption">{$captions.scoreHud_nolife}</span><div class="stage"><RhythmScoreHud score={$scoreHud_nolife.score} accuracy={$scoreHud_nolife.accuracy} life={$scoreHud_nolife.life} danger={$scoreHud_nolife.danger} failed={$scoreHud_nolife.failed} progress={$scoreHud_nolife.progress} /></div></section>
    <section class="cell" data-member="score-hud"><span class="caption">{$captions.scoreHud_overflow}</span><div class="stage"><RhythmScoreHud score={$scoreHud_overflow.score} accuracy={$scoreHud_overflow.accuracy} life={$scoreHud_overflow.life} danger={$scoreHud_overflow.danger} failed={$scoreHud_overflow.failed} progress={$scoreHud_overflow.progress} /></div></section>
    <section class="cell" data-member="results"><span class="caption">{$captions.results_default}</span><div class="stage"><RhythmResults song={$results_default.song} grade={$results_default.grade} cleared={$results_default.cleared} score={$results_default.score} previous={$results_default.previous} newBest={$results_default.newBest} maxCombo={$results_default.maxCombo} accuracy={$results_default.accuracy} mark={$results_default.mark} counts={$results_default_counts} canRetry={$results_default.canRetry} /></div></section>
    <section class="cell" data-member="results"><span class="caption">{$captions.results_failed}</span><div class="stage"><RhythmResults song={$results_failed.song} grade={$results_failed.grade} cleared={$results_failed.cleared} score={$results_failed.score} previous={$results_failed.previous} newBest={$results_failed.newBest} maxCombo={$results_failed.maxCombo} accuracy={$results_failed.accuracy} mark={$results_failed.mark} counts={$results_failed_counts} canRetry={$results_failed.canRetry} /></div></section>
    <section class="cell" data-member="results"><span class="caption">{$captions.results_fullCombo}</span><div class="stage"><RhythmResults song={$results_fullCombo.song} grade={$results_fullCombo.grade} cleared={$results_fullCombo.cleared} score={$results_fullCombo.score} previous={$results_fullCombo.previous} newBest={$results_fullCombo.newBest} maxCombo={$results_fullCombo.maxCombo} accuracy={$results_fullCombo.accuracy} mark={$results_fullCombo.mark} counts={$results_fullCombo_counts} canRetry={$results_fullCombo.canRetry} /></div></section>
    <section class="cell" data-member="results"><span class="caption">{$captions.results_allPerfect}</span><div class="stage"><RhythmResults song={$results_allPerfect.song} grade={$results_allPerfect.grade} cleared={$results_allPerfect.cleared} score={$results_allPerfect.score} previous={$results_allPerfect.previous} newBest={$results_allPerfect.newBest} maxCombo={$results_allPerfect.maxCombo} accuracy={$results_allPerfect.accuracy} mark={$results_allPerfect.mark} counts={$results_allPerfect_counts} canRetry={$results_allPerfect.canRetry} /></div></section>
    <section class="cell" data-member="results"><span class="caption">{$captions.results_disabled}</span><div class="stage"><RhythmResults song={$results_disabled.song} grade={$results_disabled.grade} cleared={$results_disabled.cleared} score={$results_disabled.score} previous={$results_disabled.previous} newBest={$results_disabled.newBest} maxCombo={$results_disabled.maxCombo} accuracy={$results_disabled.accuracy} mark={$results_disabled.mark} counts={$results_disabled_counts} canRetry={$results_disabled.canRetry} /></div></section>
    <section class="cell" data-member="results"><span class="caption">{$captions.results_empty}</span><div class="stage"><RhythmResults song={$results_empty.song} grade={$results_empty.grade} cleared={$results_empty.cleared} score={$results_empty.score} previous={$results_empty.previous} newBest={$results_empty.newBest} maxCombo={$results_empty.maxCombo} accuracy={$results_empty.accuracy} mark={$results_empty.mark} counts={$results_empty_counts} canRetry={$results_empty.canRetry} /></div></section>
    <section class="cell" data-member="results"><span class="caption">{$captions.results_overflow}</span><div class="stage"><RhythmResults song={$results_overflow.song} grade={$results_overflow.grade} cleared={$results_overflow.cleared} score={$results_overflow.score} previous={$results_overflow.previous} newBest={$results_overflow.newBest} maxCombo={$results_overflow.maxCombo} accuracy={$results_overflow.accuracy} mark={$results_overflow.mark} counts={$results_overflow_counts} canRetry={$results_overflow.canRetry} /></div></section>
